'use client';

/**
 * Spectrum UI: Footer blocks
 *
 * Four footer layouts from the Spectrum UI footer collection behind one
 * `variant` prop: a mega sitemap with region/language selectors, a link-search
 * footer that filters every page as you type, a contact footer with copy-to-
 * clipboard rows and a live local clock, and a minimal bar whose link clusters
 * open in popovers. Each layout is also exported on its own.
 */

import { BRAND, BRAND_GROUPS, BRAND_LEGAL, BRAND_SOCIALS } from './footer-blocks-kit';
import { ContactCardFooter, type ContactCardFooterProps } from './footer-blocks-contact';
import { LinkSearchFooter, type LinkSearchFooterProps } from './footer-blocks-search';
import { MinimalFooter, type MinimalFooterProps } from './footer-blocks-minimal';
import { MegaSitemapFooter, type MegaSitemapFooterProps } from './footer-blocks-sitemap';

export { ContactCardFooter, LinkSearchFooter, MinimalFooter, MegaSitemapFooter };
export type { ContactCardFooterProps, LinkSearchFooterProps, MinimalFooterProps, MegaSitemapFooterProps };
export * from './footer-blocks-kit';

export type FooterBlocksVariant = 'sitemap' | 'search' | 'contact' | 'minimal';

export interface FooterBlocksProps {
  variant?: FooterBlocksVariant;
  brand?: string;
  className?: string;
}

export function FooterBlocks({ variant = 'sitemap', brand = BRAND.name, className }: FooterBlocksProps) {
  if (variant === 'search') {
    return (
      <LinkSearchFooter
        brand={brand}
        groups={BRAND_GROUPS}
        links={BRAND_LEGAL}
        socials={BRAND_SOCIALS}
        copyright={BRAND.copyright}
        className={className}
      />
    );
  }

  if (variant === 'contact') {
    return (
      <ContactCardFooter
        brand={brand}
        email="hello@northwind.dev"
        phone="+1 (415) 555-0132"
        address="548 Market St, San Francisco, CA"
        hours="Mon–Fri, 9:00–18:00 PT"
        utcOffset={-8}
        links={BRAND_LEGAL}
        socials={BRAND_SOCIALS}
        copyright={BRAND.copyright}
        className={className}
      />
    );
  }

  if (variant === 'minimal') {
    return (
      <MinimalFooter
        brand={brand}
        clusters={BRAND_GROUPS.map((group) => ({ title: group.title, links: group.links }))}
        socials={BRAND_SOCIALS}
        copyright={BRAND.copyright}
        className={className}
      />
    );
  }

  return (
    <MegaSitemapFooter
      brand={brand}
      tagline={BRAND.tagline}
      columns={BRAND_GROUPS.map((group) => ({ groups: [group] }))}
      legal={BRAND_LEGAL}
      socials={BRAND_SOCIALS}
      regions={['United States', 'United Kingdom', 'Germany', 'Japan']}
      languages={['English', 'Deutsch', '日本語']}
      newsletter={{
        eyebrow: 'Product updates',
        blurb: 'One email a month with what shipped, what is next and nothing else.',
        cta: 'Subscribe',
      }}
      copyright={BRAND.copyright}
      className={className}
    />
  );
}

export default FooterBlocks;

/**
 * Everything the footer blocks share: the icon set, the brand lockup, the
 * social row and the bottom bar.
 *
 * The earlier blocks inlined their own glyphs so each file copied out whole.
 * That stopped scaling once every footer needed the same wordmark, the same
 * three social marks and the same bottom bar: eighteen copies of the same
 * markup drift within a week. This ships alongside each block instead: the
 * registry item lists this file too, so one install writes both.
 *
 * Two icon styles live here on purpose:
 *
 *   - Utility icons (arrows, search, check, the rest) are **outline**. A
 *     filled arrow beside 13px text reads as a blob, and a filled chevron in a
 *     select looks like a warning triangle.
 *   - Social and brand marks are **solid**, because a logo drawn in outline is
 *     not that logo. These are the same paths the live site uses.
 */

import { cn } from '@/lib/utils';

type IconProps = React.SVGProps<SVGSVGElement>;

/* ── Outline utility icons ──────────────────────────────────
   One family, one grid, one stroke weight. 1.75 sits between the
   1.5 that reads correctly next to regular text and the 2 that a
   semibold label wants, which is the mix these footers run. */

function Outline({ children, ...props }: IconProps & { children: React.ReactNode }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      {children}
    </svg>
  );
}

export function IconArrowRight(props: IconProps) {
  return (
    <Outline {...props}>
      <path d="M4.5 12h15M13 5.5l6.5 6.5L13 18.5" />
    </Outline>
  );
}

