/* ── Shared pieces ──────────────────────────────────────────
   `tone="dark"` is for the blocks that are dark in both themes, where
   `dark:` variants never fire and the light palette would be unreadable. */

export type FooterTone = 'auto' | 'dark';

/** The mark and the wordmark, locked up. */
export function BrandLockup({
  brand = BRAND.name,
  href = '/',
  tone = 'auto',
  className,
}: {
  brand?: string;
  href?: string;
  tone?: FooterTone;
  className?: string;
}) {
  return (
    <a
      href={href}
      className={cn(
        'inline-flex items-center gap-2.5 rounded-md transition-opacity duration-150 hover:opacity-70 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400',
        className,
      )}
    >
      <span
        className={cn(
          'grid size-7 shrink-0 place-items-center rounded-[7px]',
          tone === 'dark'
            ? 'bg-neutral-100 text-neutral-900'
            : 'bg-neutral-900 text-white dark:bg-neutral-100 dark:text-neutral-900',
        )}
      >
        <BrandMark className="size-3.5" />
      </span>
      <span className="whitespace-nowrap text-[14.5px] font-semibold tracking-[-0.3px]">
        {brand}
      </span>
    </a>
  );
}

/** The social row. Solid marks, 32px hit area, one hover transition. */
export function FooterSocials({
  socials = BRAND_SOCIALS,
  tone = 'auto',
  className,
}: {
  socials?: FooterSocial[];
  tone?: FooterTone;
  className?: string;
}) {
  if (socials.length === 0) return null;
  return (
    <ul className={cn('flex items-center gap-0.5', className)}>
      {socials.map(({ label, href, icon: Glyph }) => (
        <li key={label}>
          <a
            href={href}
            target="_blank"
            rel="noreferrer"
            aria-label={label}
            className={cn(
              'grid size-8 place-items-center rounded-lg transition-[color,background-color] duration-150 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400',
              tone === 'dark'
                ? 'text-neutral-400 hover:bg-white/[0.07] hover:text-neutral-100'
                : 'text-neutral-400 hover:bg-black/[0.05] hover:text-neutral-900 dark:text-neutral-500 dark:hover:bg-white/[0.07] dark:hover:text-neutral-100',
            )}
          >
            <Glyph className="size-[15px]" />
          </a>
        </li>
      ))}
    </ul>
  );
}

/**
 * The bottom bar every footer ends on: lockup and copyright left, utility links
 * and social marks right. One component rather than eighteen hand-rolled
 * copies, which is the only way they stay identical.
 */
export function FooterBar({
  brand = BRAND.name,
  copyright,
  links = BRAND_LEGAL,
  socials = BRAND_SOCIALS,
  tone = 'auto',
  showLockup = true,
  className,
}: {
  brand?: string;
  copyright?: string;
  links?: { label: string; href: string }[];
  socials?: FooterSocial[];
  tone?: FooterTone;
  showLockup?: boolean;
  className?: string;
}) {
  const muted = tone === 'dark' ? 'text-neutral-400' : 'text-neutral-500 dark:text-neutral-400';
  const hover =
    tone === 'dark'
      ? 'hover:text-neutral-100'
      : 'hover:text-neutral-900 dark:hover:text-neutral-100';
  const rule =
    tone === 'dark' ? 'border-white/[0.08]' : 'border-black/[0.07] dark:border-white/[0.08]';

  return (
    <div className={cn('border-t pt-6', rule, className)}>
      <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex flex-wrap items-center gap-x-5 gap-y-2">
          {showLockup && <BrandLockup brand={brand} tone={tone} />}
          <p className={cn('text-[12px] tabular-nums', muted)}>{copyright ?? BRAND.copyright}</p>
        </div>

        <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
          <ul className={cn('flex flex-wrap items-center gap-x-5 gap-y-2 text-[12px]', muted)}>
            {links.map((link) => (
              <li key={link.label}>
                <a
                  href={link.href}
                  className={cn(
                    'transition-colors duration-150 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400',
                    hover,
                  )}
                >
                  {link.label}
                </a>
              </li>
            ))}
          </ul>
          <FooterSocials socials={socials} tone={tone} className="-mr-2" />
        </div>
      </div>
    </div>
  );
}

'use client';

import { useId, useState, type CSSProperties } from 'react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import {
  IconArrowRight,
  IconChevronDown,
  IconLocation,
  BrandLockup,
  FooterSocials,
  type FooterSocial,
} from './footer-blocks-kit';

const KEYFRAMES = `
@keyframes su-footer-panel { from { opacity: 0; transform: translateY(-4px) } to { opacity: 1; transform: none } }
@keyframes su-footer-rise { from { opacity: 0; transform: translateY(16px) } to { opacity: 1; transform: none } }

/* Columns resolve left to right as the footer scrolls into the page, on a view()
   timeline rather than on mount: a footer's entrance has to fire when you
   arrive at it, and a mount animation is over before you get there. The stagger
   is a shifted animation-range per column, since animation-delay does nothing on
   a scroll timeline.

   The links are never gated on this. Without scroll-driven animation support the
   rule does not apply at all and the server-rendered resting state is what shows;
   with it, \`entry\` is guaranteed to reach 100% for anything at the end of a
   document, so the columns cannot be stranded part-way through the fade. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .su-sitemap-column {
      animation: su-footer-rise linear both;
      animation-timeline: view();
      animation-range: entry var(--su-from) entry calc(var(--su-from) + 48%);
    }
  }
}
`;

export type MegaSitemapFooterVariant = 'Expanded' | 'Compact';

export interface MegaSitemapLink {
  label: string;
  href: string;
  badge?: string;
}

export interface MegaSitemapGroup {
  title: string;
  links: MegaSitemapLink[];
  seeAll?: { label: string; href: string };
}

export interface MegaSitemapColumn {
  groups: MegaSitemapGroup[];
}

export interface MegaSitemapFooterProps {
  brand: string;
  tagline?: string;
  columns: MegaSitemapColumn[];
  legal?: { label: string; href: string }[];
  socials?: FooterSocial[];
  regions?: string[];
  languages?: string[];
  newsletter?: { eyebrow: string; blurb: string; cta: string };
  onSubscribe?: () => void;
  copyright?: string;
  variant?: MegaSitemapFooterVariant;
  className?: string;
}

function GroupBlock({ group, compact }: { group: MegaSitemapGroup; compact: boolean }) {
  return (
    <div>
      <p className="font-mono text-[10.5px] font-medium uppercase tracking-[0.09em] text-neutral-500 dark:text-neutral-400">
        {group.title}
      </p>
      <ul className={cn('mt-3.5 space-y-2', compact && 'mt-3 space-y-1.5')}>
        {group.links.map((link) => (
          <li key={link.label}>
            <a
              href={link.href}
              className="group/link text-[13.5px] leading-[1.5] text-neutral-800 transition-colors duration-150 hover:text-black focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400 dark:text-neutral-200 dark:hover:text-white"
            >
              <span className="relative">
                {link.label}
                <span
                  aria-hidden
                  className="absolute inset-x-0 -bottom-px h-px origin-left scale-x-0 bg-current transition-transform duration-[220ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-hover/link:scale-x-100 motion-reduce:transition-none"
                />
              </span>
              {link.badge && (
                <span className="ml-1.5 inline-block whitespace-nowrap rounded-full bg-black/[0.05] px-1.5 py-px align-[0.06em] font-mono text-[9.5px] uppercase tracking-[0.06em] tabular-nums text-neutral-600 dark:bg-white/[0.08] dark:text-neutral-300">
                  {link.badge}
                </span>
              )}
            </a>
          </li>
        ))}
      </ul>
      {group.seeAll && (
        <a
          href={group.seeAll.href}
          className="group mt-3.5 inline-flex items-center gap-1 text-[12.5px] font-medium text-neutral-900 transition-colors duration-150 hover:text-black focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400 dark:text-neutral-100"
        >
          {group.seeAll.label}
          <IconArrowRight className="size-3.5 transition-transform duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:translate-x-0.5 motion-reduce:transition-none" />
        </a>
      )}
    </div>
  );
}

function AccordionGroup({ group, index }: { group: MegaSitemapGroup; index: number }) {
  const [open, setOpen] = useState(index === 0);
  const panelId = `${useId()}-panel`;

  return (
    <div className="border-b border-black/[0.07] dark:border-white/[0.08]">
      <button
        type="button"
